// === Tab: mySketch ===
ArrayList<Attractor> attractors;
ArrayList<Agent> agents;

let doClear = false;
let play = true;
let mirror = true;
let rotate = true;

function setup(){   
  createCanvas(1024, 768);
  background(0);
  colorMode(HSB,360,100,100,100);
  noStroke();
  frameRate(60);

  attractors = new ArrayList<Attractor>();
  agents = new ArrayList<Agent>();

  for(i = 0; i < 0; i++){
    let a = new Attractor();    
    attractors.add(a);
  }

  for(i = 0; i < 1500; i++){
    var a = new Agent();    
    agents.add(a);
  }
}

function draw(){

  if(doClear){
  	background(0);

    agents.clear();
    attractors.clear();

    for(i = 0; i < 2000; i++){
      var a = new Agent();    
      agents.add(a);
    }

    doClear = false;
  }

  if(play){
    fill(0,0,0,10);
    noStroke();
    rect(0,0,width,height);
    for(i = 0; i < agents.size(); i++){
      agents.get(i).update();
    }
  }

  for(i = 0; i < attractors.size(); i++){
    attractors.get(i).update();
  }
}

function mouseClicked(){
  var a = new Attractor((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
  attractors.add(a);

  if(mirror){
    var a = new Attractor(width-(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))),(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    attractors.add(a);
  }
}

function keyPressed() {
  if (key == 32) {    
    //doClear = true;
  }

  if(key == 'Q' || key == 'q'){
    for(i = 0; i < agents.size(); i++){
      agents.get(i).reset();
    }
  }

  if(key == 'M' || key == 'm'){
    mirror = !mirror;
  }

  if (key == 10) {    
    play = !play;
  }
}

class Agent {
  oPos;
  nPos;
  vel;
  mass;
  c;

  constructor(){
    oPos = new PVector(0,0);
    nPos = new PVector(0,0);
    vel = new PVector(0,0);
    c = color(0,100,100); //color(random(360), 50, 70);
    mass = 1;
    reset();
  }

  function update(){
    let doReset = false;

    for(i = 0; i < attractors.size(); i++){
      var a = attractors.get(i);

      if(PVector.dist(nPos, a.pos) < 10){
        doReset = true;
      }

      let d2 = pow(PVector.dist(nPos, a.pos),2);

      let n = PVector.sub(a.pos,nPos);
      n.normalize();
      let f = 100 * (a.mass*mass) / d2;

      n.mult(f);
      vel.add(n);
    }    

    nPos.add(vel);    

    if(doReset == true) {
      reset();
    }
    if(nPos.x < 0){
      reset();
    }
    if(nPos.y < 0){
      reset();
    }
    if(nPos.x > width){
      reset();
    }
    if(nPos.y > height){
      reset();
    }

    c = color(vel.mag()*80,90,vel.mag()*40+60); 
    stroke(c);
    strokeWeight(3);
    line(oPos.x, oPos.y, nPos.x, nPos.y);
    oPos = new PVector(nPos.x,nPos.y);
  }

  function reset(){
    vel = new PVector(0,0);

    let dir = int(random(4));

    if(dir == 0){
       nPos = new PVector(random(width),0);
    }
    if(dir == 1){
       nPos = new PVector(random(width),height);
    }
    if(dir == 2){
       nPos = new PVector(0,random(height));
    }
    if(dir == 3){
       nPos = new PVector(width,random(height));
    }

    oPos = new PVector(nPos.x,nPos.y);
  }
}

class Attractor {
  pos;
  mass;

  constructor(x, y){    
    pos = new PVector(x, y);
    mass = 1;
  }

  function update(){
    fill(0,0,100);
    noStroke();
    ellipse(pos.x, pos.y , 5, 5);
  }
}

